require dirname(__DIR__).'/bootstrap.php';require __DIR__.'/admin-layout.php';admin_required();$id=(int)($_GET['id']??$_POST['id']??0);$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch()?:['name'=>'','sku'=>'','slug'=>'','category_id'=>null,'description'=>'','long_description'=>'','price'=>'','sale_price'=>'','stock'=>0,'active'=>1,'featured'=>0,'image'=>''];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$name=trim($_POST['name']??'');$sku=trim($_POST['sku']??'');$slug=trim($_POST['slug']??'')?:strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/','-', $name),'-'));$price=(float)($_POST['price']??0);$sale=($_POST['sale_price']??'')===''?null:(float)$_POST['sale_price'];$stock=(int)($_POST['stock']??0);if(!$name||!$sku||$price<0||$stock<0||($sale!==null&&($sale<0||$sale>=$price)))throw new RuntimeException('Check required fields and prices. Sale price must be lower than regular price.');$image=$p['image'];$uploaded=upload_image($_FILES['image']??[]);if($uploaded)$image=$uploaded;$data=[$name,$sku,$slug,(int)($_POST['category_id']??0)?:null,trim($_POST['description']??''),trim($_POST['long_description']??''),$price,$sale,$stock,$image,isset($_POST['active'])?1:0,isset($_POST['featured'])?1:0];if($id){$data[]=$id;$pdo->prepare('UPDATE products SET name=?,sku=?,slug=?,category_id=?,description=?,long_description=?,price=?,sale_price=?,stock=?,image=?,active=?,featured=?,updated_at=NOW() WHERE id=?')->execute($data);}else{$pdo->prepare('INSERT INTO products(name,sku,slug,category_id,description,long_description,price,sale_price,stock,image,active,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);}flash('Product saved.');redirect('products.php');}catch(Throwable $e){$error=$e->getMessage();}}
$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();admin_header($id?'Edit product':'Add product');if($error)echo '<div class="notice error">'.e($error).'</div>'; ?><form method="post" enctype="multipart/form-data" class="admin-form admin-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Product name *<input name="name" required value="<?=e($p['name'])?>"></label><label>SKU *<input name="sku" required value="<?=e($p['sku'])?>"></label><label>Slug<input name="slug" value="<?=e($p['slug'])?>"></label><label>Category<select name="category_id"><option value="">None</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($p['category_id']==$c['id']?'selected':'')?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Short description<textarea name="description"><?=e($p['description'])?></textarea></label><label>Full description<textarea name="long_description"><?=e($p['long_description'])?></textarea></label><label>Regular price<input type="number" step="0.01" min="0" name="price" required value="<?=e((string)$p['price'])?>"></label><label>Sale price (optional)<input type="number" step="0.01" min="0" name="sale_price" value="<?=e((string)$p['sale_price'])?>"></label><label>Stock<input type="number" min="0" name="stock" required value="<?=e((string)$p['stock'])?>"></label><label>Product image (JPG, PNG, WEBP; max 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp" onchange="previewImage(this,'image-preview')"><img id="image-preview" class="upload-preview" src="<?=e('../'.product_image($p['image']))?>" alt="Preview"></label><label><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> Active</label><label><input type="checkbox" name="featured" <?=$p['featured']?'checked':''?>> Featured</label><button class="button">SAVE PRODUCT</button></form><?php admin_footer(); ?>
